import json, os, subprocess, sys
from pathlib import Path

number=int(sys.argv[1])
repo='21nCo/super-functions'
root=Path('/tmp/superfunctions-docs-pr-snapshots-20260929')
root.mkdir(exist_ok=True)
env=os.environ.copy(); env['GH_CONFIG_DIR']='/Users/serro/.config/gh-other'

def gh(*args):
    p=subprocess.run(['gh',*map(str,args)],env=env,capture_output=True,text=True)
    if p.returncode: raise RuntimeError(f'gh {args}: {p.stderr[:1000]}')
    return json.loads(p.stdout)

def graphql(query,**vars):
    args=['api','graphql','-f','query='+query]
    for k,v in vars.items():
        if v is not None: args.extend(['-F',f'{k}={v}'])
    return gh(*args)

def pages(path):
    result=[]; page=1
    while True:
        batch=gh('api',f'{path}{"&" if "?" in path else "?"}per_page=100&page={page}')
        if not isinstance(batch,list): raise RuntimeError(f'Expected list from {path}')
        result.extend(batch)
        if len(batch)<100: break
        page+=1
    return result

meta=gh('pr','view',number,'--repo',repo,'--json','headRefOid,headRefName,url,statusCheckRollup,title')
sha=meta['headRefOid']
q='''query($number:Int!,$cursor:String) { repository(owner:"21nCo",name:"super-functions") { pullRequest(number:$number) { reviewThreads(first:100,after:$cursor) { nodes { id isResolved path comments(first:100) { nodes { body author { login } createdAt outdated url originalLine line } pageInfo { hasNextPage endCursor } } } pageInfo { hasNextPage endCursor } } } } }'''
threads=[]; cursor=None
while True:
    data=graphql(q,number=number,cursor=cursor)['data']['repository']['pullRequest']['reviewThreads']
    threads.extend(data['nodes'])
    if not data['pageInfo']['hasNextPage']: break
    cursor=data['pageInfo']['endCursor']
q2='''query($id:ID!,$cursor:String) { node(id:$id) { ... on PullRequestReviewThread { comments(first:100,after:$cursor) { nodes { body author { login } createdAt outdated url originalLine line } pageInfo { hasNextPage endCursor } } } } }'''
for thread in threads:
    connection=thread['comments']
    while connection['pageInfo']['hasNextPage']:
        connection=graphql(q2,id=thread['id'],cursor=connection['pageInfo']['endCursor'])['data']['node']['comments']
        thread['comments']['nodes'].extend(connection['nodes'])
    thread['comments']=thread['comments']['nodes']
reviews=pages(f'repos/{repo}/pulls/{number}/reviews')
issue_comments=pages(f'repos/{repo}/issues/{number}/comments')
inline_comments=pages(f'repos/{repo}/pulls/{number}/comments')
checks=pages(f'repos/{repo}/commits/{sha}/check-runs') if False else gh('api',f'repos/{repo}/commits/{sha}/check-runs?per_page=100')
check_runs=checks['check_runs']
if checks['total_count']>len(check_runs):
    page=2
    while len(check_runs)<checks['total_count']:
        check_runs.extend(gh('api',f'repos/{repo}/commits/{sha}/check-runs?per_page=100&page={page}')['check_runs']);page+=1
for check in check_runs:
    if check['conclusion'] in ('failure','timed_out','action_required','startup_failure'):
        check['annotations']=pages(f'repos/{repo}/check-runs/{check["id"]}/annotations')
statuses=gh('api',f'repos/{repo}/commits/{sha}/status')
end=gh('pr','view',number,'--repo',repo,'--json','headRefOid')
if end['headRefOid']!=sha: raise RuntimeError(f'head changed during snapshot: {sha} -> {end["headRefOid"]}')
snapshot={'meta':meta,'threads':threads,'reviews':reviews,'issue_comments':issue_comments,'inline_comments':inline_comments,'check_runs':check_runs,'statuses':statuses}
(root/f'PR-{number}.json').write_text(json.dumps(snapshot,indent=2))
print(json.dumps({'pr':number,'head':sha,'threads':len(threads),'unresolved':sum(not t['isResolved'] for t in threads),'reviews':len(reviews),'issue_comments':len(issue_comments),'inline_comments':len(inline_comments),'check_runs':[(c['name'],c['status'],c['conclusion'],len(c.get('annotations',[]))) for c in check_runs],'statuses':[(s['context'],s['state']) for s in statuses['statuses']]},indent=2))
for t in threads:
    if not t['isResolved']:
        print('THREAD',t['path'],t['comments'][-1]['url'] if t['comments'] else '',(t['comments'][-1]['body'] if t['comments'] else '').split('\\n')[0][:350])

