import json, subprocess, pathlib
root=pathlib.Path('/tmp/sf-docs-review-20260930')
prs=[p for p in json.loads((root/'prs.json').read_text()) if p['title'].startswith('docs(') or p['number']==133]
def cmd(*args):
 p=subprocess.run(args,text=True,capture_output=True)
 if p.returncode: raise RuntimeError(str(args)+p.stderr+p.stdout)
 return p.stdout
out={}
for pr in prs:
 n=pr['number']; branch=pr['headRefName']
 if n==133: path='/Users/serro/Documents/dev/n/worktrees/superfunctions/PR-133'
 elif n==222: path='/private/tmp/superfunctions-PR-222'
 else:
  receipt=json.loads(cmd('orca','worktree','create','--name',f'docs-pr-{n}-review-20260930','--base-branch','origin/'+branch,'--setup','skip','--json'))
  (root/f'create-{n}.json').write_text(json.dumps(receipt,indent=2))
  path=receipt['result']['worktree']['path']
 status=cmd('git','-C',path,'status','--porcelain')
 if any(not line.startswith('?? ') for line in status.splitlines()): raise RuntimeError(f'Dirty tracked state PR {n}: {status}')
 # Preserve untracked artifacts. Never reset an existing local head.
 current=cmd('git','-C',path,'branch','--show-current').strip()
 if current!=branch:
  exists=subprocess.run(['git','show-ref','--verify','--quiet','refs/heads/'+branch]).returncode==0
  cmd('git','-C',path,'switch',branch) if exists else cmd('git','-C',path,'switch','-c',branch,'--track','origin/'+branch)
 sha=cmd('git','-C',path,'rev-parse','HEAD').strip()
 if sha!=pr['headRefOid']:
  cmd('git','-C',path,'merge','--ff-only','origin/'+branch)
 sha=cmd('git','-C',path,'rev-parse','HEAD').strip()
 if sha!=pr['headRefOid']: raise RuntimeError(f'Wrong head PR {n}: {sha}')
 out[str(n)]={'path':path,'branch':branch,'head':sha,'status':cmd('git','-C',path,'status','--short'),'remotes':cmd('git','-C',path,'remote','-v')}
 (root/'worktrees.json').write_text(json.dumps(out,indent=2))
 print(n,path,sha,flush=True)

